export const ASCENSION_MAX=100;
export const WING_LEVELS=Array.from({length:100},(_,i)=>i===99?250:Math.round((10+i*240/99)/5)*5);
export const AURA_LEVELS=Array.from({length:100},(_,i)=>i===99?250:Math.round((20+i*230/99)/5)*5);
export const ASCENSION_TIERS=[{min:0,name:'Comum',color:'#ffffff',key:'common'},{min:20,name:'Raro',color:'#55ff55',key:'rare'},{min:40,name:'Épico',color:'#aa00aa',key:'epic'},{min:60,name:'Lendário',color:'#ffaa00',key:'legendary'},{min:80,name:'Místico / Divino',color:'#00ffff',key:'divine'},{min:100,name:'Ultra Primordial',color:'#00ffff',key:'ultra'}];
export function ascensionTier(rank){return ASCENSION_TIERS.filter(t=>rank>=t.min).at(-1)||ASCENSION_TIERS[0];}
export const STYLES={mystic:{name:'Mística',color:'#00ffff'},nature:{name:'Veneno Celeste',color:'#55ff55'},void:{name:'Vazio Estelar',color:'#e73dff'},infernal:{name:'Coroa Rubra',color:'#ff3265'},solar:{name:'Solar',color:'#ffaa00'},glacial:{name:'Glacial',color:'#00dfff'},eclipse:{name:'Eclipse',color:'#bd45ff'},carmim:{name:'Carmim',color:'#ff4169'}};
export function initAscension(p){p.wings||={rank:0,style:p.classId==='ARC'?'mystic':p.classId==='ESP'||p.classId==='LAS'?'eclipse':'solar',visible:true};p.aura||={rank:0,style:p.classId==='RUP'?'carmim':p.classId==='ARC'?'mystic':'solar',visible:true};p.materials||={};p.wallet||={cash:0};p.appearances||=[];p.regionClears||={};p.pvpWins||=0;p.pvpLosses||=0;p.heroId||='hero-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}
export function ascensionForm(kind,rank){if(!rank)return 'Adormecida';const names=kind==='wings'?['Plumas do Despertar','Cristal da Serpente','Lâminas da Nebulosa','Serafim de Hélion','Asa Divina — Prisma Místico','Asas da Origem Primordial']:['Centelha Interior','Espiral da Selva','Ressonância do Vazio','Coroa de Hélion','Domínio Divino — Prisma Místico','Aura da Origem Primordial'];return names[rank<20?0:rank<40?1:rank<60?2:rank<80?3:rank<100?4:5];}
export function ascensionCost(p,kind){const r=p[kind]?.rank||0,n=r+1;return {rank:n,level:(kind==='wings'?WING_LEVELS:AURA_LEVELS)[r]||250,gold:Math.round(500*n*n),material:kind==='wings'?'Pluma Astral':'Essência de Aura',count:Math.ceil(5*n**1.55),cores:n>=35?Math.ceil((n-33)/3):0};}
export function evolveAscension(p,kind){initAscension(p);if(!['wings','aura'].includes(kind))return {ok:false,reason:'Evolução inválida.'};if(p[kind].rank>=ASCENSION_MAX)return {ok:false,reason:'Evolução máxima.'};const c=ascensionCost(p,kind);if(p.level<c.level)return {ok:false,reason:'Requer nível '+c.level+'.'};if(p.gold<c.gold||(p.materials[c.material]||0)<c.count||(p.materials['Núcleo de Cataclismo']||0)<c.cores)return {ok:false,reason:'Faltam ouro ou materiais. Veja as fontes nesta janela.'};p.gold-=c.gold;p.materials[c.material]-=c.count;if(c.cores)p.materials['Núcleo de Cataclismo']-=c.cores;p[kind].rank++;return {ok:true,rank:p[kind].rank};}
export function ascensionBonuses(p){const w=p.wings?.rank||0,a=p.aura?.rank||0,scale=r=>Math.min(10,r)+Math.max(0,Math.min(50,r)-10)*.25+Math.max(0,Math.min(100,r)-50)*.1;return {attackPct:scale(w)*.012,accuracy:Math.round(scale(w)*20),hpPct:scale(a)*.008,defensePct:scale(a)*.012,critd:scale(a)*.005};}
export function regionAccess(p,index,regions,power=Infinity){if(p.testMode)return {ok:true,reason:'Laboratório: acesso de teste.'};const region=regions[index];if(!region)return {ok:false,reason:'Região inválida.'};if(p.level<region.range[0])return {ok:false,reason:'Requer nível '+region.range[0]+'.'};const minimumPower=Math.round(2400*(1+region.range[0]/35)**1.2);if(index>0&&power<minimumPower)return {ok:false,reason:'Requer poder '+minimumPower.toLocaleString('pt-BR')+'.'};if(index>0&&!(p.regionClears?.[index-1]>0))return {ok:false,reason:'Conclua uma DG da região anterior: '+regions[index-1].name+'.'};if(index===1&&p.quest<4)return {ok:false,reason:'Conclua o capítulo do farol.'};return {ok:true,reason:'Acesso liberado.'};}
export const CASH_PRODUCTS=[{id:'extensor',name:'Extensor Astral',kind:'material',price:25000,minLevel:175,material:'Extensor Astral',count:1,description:'Abre o 3º slot de uma peça SS+ ou superior, nível175+. Mesmo extensor obtido nos Cataclismos. Aplicação na peça pelo inventário.'},{id:'w-eclipse',name:'Asas do Eclipse Rubro',kind:'appearance',price:300,style:'infernal',target:'wings',description:'Traços carmim nas asas. Aparência, sem bônus de poder.'},{id:'a-eclipse',name:'Aura do Vazio Violeta',kind:'appearance',price:220,style:'void',target:'aura',description:'Energia violeta e órbitas arcanas. Aparência, sem bônus de poder.'},{id:'feathers',name:'Suprimento de Plumas',kind:'material',price:120,material:'Pluma Astral',count:30,description:'30 plumas. Também obtidas em caça e DGs.'},{id:'essence',name:'Suprimento de Essência',kind:'material',price:120,material:'Essência de Aura',count:30,description:'30 essências. Também obtidas em caça e DGs.'}];
export function buyCashProduct(p,id){initAscension(p);const item=CASH_PRODUCTS.find(x=>x.id===id);if(!item)return {ok:false,reason:'Produto inexistente.'};if(p.level<(item.minLevel||1))return {ok:false,reason:'Requer nível '+item.minLevel+'.'};if((p.wallet.cash||0)<item.price)return {ok:false,reason:'Cash insuficiente. Ouro e cash são moedas separadas.'};if(item.kind==='appearance'&&p.appearances.includes(id))return {ok:false,reason:'Aparência já adquirida.'};p.wallet.cash-=item.price;if(item.kind==='material')p.materials[item.material]=(p.materials[item.material]||0)+item.count;else {p.appearances.push(id);p[item.target].style=item.style;}return {ok:true};}
export function recordHero(rows,p,power){if(p.testMode)return rows;const entry={id:p.heroId,name:p.name,classId:p.classId,level:p.level,power,powerVersion:2,wins:p.pvpWins||0,losses:p.pvpLosses||0,updatedAt:Date.now()};return [...rows.filter(r=>r.id!==entry.id),entry].slice(-100);}
export function rankHeroes(rows,type='power'){return rows.slice().sort((a,b)=>type==='pvp'?b.wins-a.wins||a.losses-b.losses||b.power-a.power:b.power-a.power||b.level-a.level);}
